_NUMBER = re.compile(r"^(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?$")

_DR_SUFFIX = re.compile(r"\s*DR$", re.IGNORECASE)
_CURRENCY = "₹$"


def _parse_date(raw):
    """Return an ISO date string, or None if `raw` isn't a valid supported date."""
    s = raw.strip()

    m = _DMY.match(s)
    if m:
        day, month, year = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        m = _ISO.match(s)
        if m:
            year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            m = _DMONY.match(s)
            if not m:
                return None
            month = _MONTHS.get(m.group(2).lower())
            if month is None:
                return None
            day, year = int(m.group(1)), int(m.group(3))

    try:
        return date(year, month, day).isoformat()
    except ValueError:  # e.g. 31/02/2026
        return None


def _parse_amount(raw):
    """Return a float (negative for debits), or None if `raw` isn't a valid amount."""
    s = raw.strip()
    negative = False

    # ` DR` suffix and/or (parentheses) both mark a debit; either may wrap the other.
    for _ in range(2):
        stripped = _DR_SUFFIX.sub("", s)
        if stripped != s:
            negative = True
            s = stripped.strip()
        if len(s) >= 2 and s.startswith("(") and s.endswith(")"):
            negative = True
            s = s[1:-1].strip()
        if s[:1] in _CURRENCY:
            s = s[1:].strip()

    if not _NUMBER.match(s):
        return None

    value = float(s.replace(",", ""))
    return -value if negative else value


