        raw = raw.strip()
        for pattern, order in ((_DMY, "dmy"), (_ISO, "ymd"), (_DMONY, "dby")):
            m = pattern.match(raw)
            if not m:
                continue
            if order == "dmy":
                day, month, year = int(m.group(1)), int(m.group(2)), int(m.group(3))
            elif order == "ymd":
                year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
            else:
                month = _MONTHS.get(m.group(2).lower())
                if month is None:
                    return None
                day, year = int(m.group(1)), int(m.group(3))
            try:
                return date(year, month, day).isoformat()
            except ValueError:
                return None
        return None

    def parse_amount(raw):
        s = raw.strip()
        if not s:
            return None
        negative = False

        # ' DR' suffix marks a debit (case-insensitive, whitespace-tolerant).
        m = re.match(r"^(.*?)\s+DR$", s, re.IGNORECASE)
        if m:
            negative = True
            s = m.group(1).strip()

        # Parentheses also mark a debit, outside or inside the currency symbol.
        if s.startswith("(") and s.endswith(")"):
            negative = True
            s = s[1:-1].strip()

        if s[:1] in ("\u20b9", "$"):
            s = s[1:].strip()

        if s.startswith("(") and s.endswith(")"):
            negative = True
            s = s[1:-1].strip()

        if not _NUMBER.match(s):
