        else:
            m = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", s)
            if m:
                year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
            else:
                m = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})", s)
                if not m:
                    return None
                day, year = int(m.group(1)), int(m.group(3))
                month = months.get(m.group(2).lower())
