        s = raw.strip()
        negative = False
        # Currency symbols, parentheses and a DR suffix can nest in either
        # order (e.g. "(₹1,200.50)" or "₹(1,200.50)"), so peel until stable.
        while True:
            before = s
            if len(s) >= 2 and s.startswith("(") and s.endswith(")"):
