def merge_busy2(intervals, cancels):
    from collections import Counter

    add = {}
    rem = {}
    cdelta = {}
    points = set()

    for s, e, p in intervals:
        if s >= e:
            continue
        add.setdefault(s, []).append(p)
        rem.setdefault(e, []).append(p)
        points.add(s)
        points.add(e)

    for s, e in cancels:
        if s >= e:
            continue
        cdelta[s] = cdelta.get(s, 0) + 1
        cdelta[e] = cdelta.get(e, 0) - 1
        points.add(s)
        points.add(e)

    if not points:
        return []

    points = sorted(points)
    active = Counter()
    cancel_depth = 0
    result = []

    for i in range(len(points) - 1):
        x = points[i]

        # ends close before starts open, so touching intervals never overlap
        for p in rem.get(x, ()):
            active[p] -= 1
            if active[p] == 0:
                del active[p]
        for p in add.get(x, ()):
            active[p] += 1
        cancel_depth += cdelta.get(x, 0)

        if not active or cancel_depth > 0:
            continue

        prio = max(active)
        nxt = points[i + 1]
        if result and result[-1][1] == x and result[-1][2] == prio:
            result[-1] = (result[-1][0], nxt, prio)
        else:
            result.append((x, nxt, prio))

    return result

