        self._chain = {name: self._build_chain(name) for name in spec}

    def _build_chain(self, name):
        chain = []
        seen = set()
        node = name
        while node is not None:
            if node in seen:
                raise ValueError("cycle in rate tree at %r" % (node,))
            if node not in self._parent:
                raise KeyError("unknown node %r" % (node,))
            seen.add(node)
            chain.append(node)
            node = self._parent[node]
