            self._tokens[node] = min(
                self._capacity[node],
                self._tokens[node] + elapsed * self._rate[node],
            )
            self._last[node] = now

    def allow(self, name, n=1.0, now=0.0):
        chain = self._chain[name]           # KeyError for unknown node
        n = float(n)
        now = float(now)
        for node in chain:
            self._refill(node, now)
        if any(self._tokens[node] < n for node in chain):
            return False
        for node in chain:
            self._tokens[node] -= n
        return True

