    """Hierarchical token buckets: a request debits a node and all its ancestors."""

    def __init__(self, spec):
        self._cap = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self._cap[name] = float(capacity)
            self._rate[name] = float(refill_rate)
            self._parent[name] = parent
            self._tokens[name] = float(capacity)  # buckets start full
            self._last[name] = None               # set on first touch
        # Precompute node -> [node, ..., root] so each call is a dict lookup.
        self._chain = {name: self._build_chain(name) for name in spec}

    def _build_chain(self, name):
        chain = []
        seen = set()
        cur = name
        while cur is not None:
            if cur in seen:
                raise ValueError("cycle in rate tree at %r" % (cur,))
            seen.add(cur)
            chain.append(cur)
            cur = self._parent[cur]
        return chain

    def _refill(self, name, now):
        """Advance one node's bucket to `now` and return its available tokens."""
        last = self._last[name]
        if last is None:
            self._last[name] = now
            return self._tokens[name]
        elapsed = now - last
        if elapsed > 0.0:
            self._tokens[name] = min(
                self._cap[name], self._tokens[name] + elapsed * self._rate[name]
            )
            self._last[name] = now
        return self._tokens[name]

    def allow(self, name, n=1.0, now=0.0):
        chain = self._chain[name]
        n = float(n)
        now = float(now)
        # Touching a node refills it whether or not the request succeeds;
        # only the debit is all-or-nothing.
        available = [self._refill(node, now) for node in chain]
        if any(avail < n for avail in available):
            return False
        for node in chain:
            self._tokens[node] -= n
        return True

class RateTree:
    """Hierarchical token-bucket limiter: a request debits a node and all its ancestors."""

    def __init__(self, spec):
        self._cap = {}
        self._rate = {}
        self._parent = {}
        self._tokens = {}
        self._last = {}

        for name, (capacity, refill_rate, parent) in spec.items():
            self._cap[name] = float(capacity)
            self._rate[name] = float(refill_rate)
            self._parent[name] = parent
            self._tokens[name] = float(capacity)  # buckets start full
            self._last[name] = None               # first touch sets the clock

        for name, parent in self._parent.items():
            if parent is not None and parent not in self._cap:
                raise KeyError("unknown parent %r for node %r" % (parent, name))

        roots = [n for n, p in self._parent.items() if p is None]
        if len(roots) != 1:
            raise ValueError("spec must have exactly one root, found %d" % len(roots))
        self._root = roots[0]

        self._chains = {}
        for name in self._cap:
            self._chain(name)

    def _chain(self, name):
        """Node plus every ancestor up to the root, cached."""
        cached = self._chains.get(name)
        if cached is not None:
            return cached

        chain = []
        seen = set()
        cur = name
        while cur is not None:
            if cur in seen:
                raise ValueError("cycle in spec at node %r" % cur)
            seen.add(cur)
            chain.append(cur)
            cur = self._parent[cur]

        self._chains[name] = chain
        return chain

    def _refill(self, name, now):
        last = self._last[name]
        if last is None:
            self._last[name] = now
            return
        elapsed = now - last
        if elapsed <= 0.0:  # clock went backwards (or stood still): no refill, no rewind
            if elapsed == 0.0:
                self._last[name] = now
            return
        self._tokens[name] = min(self._cap[name], self._tokens[name] + elapsed * self._rate[name])
        self._last[name] = now

    def allow(self, name, n=1.0, now=0.0):
        if name not in self._cap:
            raise KeyError("unknown node %r" % name)

        n = float(n)
        now = float(now)
        chain = self._chain(name)

        for node in chain:
            self._refill(node, now)

        for node in chain:
            if self._tokens[node] < n:
                return False  # all-or-nothing: nothing debited anywhere

        for node in chain:
            self._tokens[node] -= n
        return True

