        (re.compile(r"\s*(\d{4})-(\d{1,2})-(\d{1,2})"), "ymd"),
        (re.compile(r"\s*(\d{1,2})\s+(%s)\s+(\d{4})" % _mon), "dmy_name"),
        (re.compile(r"\s*(%s)\s+(\d{1,2}),\s*(\d{4})" % _mon), "mdy_name"),
    ]
