        """Return (iso_date, index_just_after_the_field_separator) or None."""
        for pat, kind in DATE_PATTERNS:
            m = pat.match(line)
            if not m:
                continue
            j = m.end()
            while j < len(line) and line[j] in " \t":
                j += 1
            if j >= len(line) or line[j] != ",":
                continue  # date must be followed by a field separator
            a, b, c = m.groups()
            if kind == "dmy":
                y, mo, d = int(c), int(b), int(a)
            elif kind == "ymd":
                y, mo, d = int(a), int(b), int(c)
            elif kind == "dmy_name":
                y, mo, d = int(c), MONTHS[b], int(a)
            else:  # mdy_name
                y, mo, d = int(c), MONTHS[a], int(b)
            try:
                return _date(y, mo, d).isoformat(), j + 1
            except ValueError:
                return None
        return None

    def parse_description(line, i):
        """Return (description, index_just_after_the_field_separator) or None."""
        j = i
        while j < len(line) and line[j] in " \t":
            j += 1
        if j < len(line) and line[j] == '"':
            out = []
            j += 1
            closed = False
            while j < len(line):
                ch = line[j]
                if ch == '"':
                    if j + 1 < len(line) and line[j + 1] == '"':
                        out.append('"')
                        j += 2
                        continue
                    j += 1
                    closed = True
                    break
                out.append(ch)
                j += 1
            if not closed:
                return None
            while j < len(line) and line[j] in " \t":
                j += 1
            if j >= len(line) or line[j] != ",":
                return None
            return "".join(out).strip(), j + 1
        k = line.find(",", i)
        if k == -1:
            return None
        return line[i:k].strip(), k + 1

    def parse_amount(s):
        s = s.strip()
        neg = False
        if s.endswith(" DR"):
            neg = True
            s = s[:-3].strip()
        for _ in range(2):  # handles "(<sym>N)" and "<sym>(N)"
            if len(s) >= 2 and s.startswith("(") and s.endswith(")"):
                neg = True
                s = s[1:-1].strip()
            if s[:1] in SYMBOLS:
                s = s[1:].strip()
        if not s or not AMOUNT_RE.fullmatch(s):
            return None
        val = float(s.replace(",", ""))
        return -val if neg else val

    rows = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        got = parse_date(line)
        if got is None:
