    DMONY_RE = re.compile(r"^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$")
    MONDY_RE = re.compile(r"^([A-Za-z]{3})\s+(\d{1,2})\s*,\s*(\d{4})$")
    MOND_HEAD_RE = re.compile(r"^([A-Za-z]{3})\s+(\d{1,2})$")
    YEAR_RE = re.compile(r"^\d{4}$")

    def split_fields(line):
        """CSV-ish split: quotes only recognised at the start of a field."""
        fields = []
        i, n = 0, len(line)
        while True:
            j = i
            while j < n and line[j] in " \t":
                j += 1
            if j < n and line[j] == '"':
                j += 1
                buf = []
                while True:
                    if j >= n:
                        return None  # unterminated quote
                    c = line[j]
                    if c == '"':
                        if j + 1 < n and line[j + 1] == '"':
                            buf.append('"')
                            j += 2
                        else:
                            j += 1
                            break
                    else:
                        buf.append(c)
                        j += 1
                k = j
                while k < n and line[k] in " \t":
                    k += 1
                if k < n and line[k] != ",":
                    return None  # junk after closing quote
                fields.append("".join(buf))
                if k >= n:
                    return fields
                i = k + 1
            else:
                k = line.find(",", i)
                if k == -1:
                    fields.append(line[i:])
                    return fields
                fields.append(line[i:k])
                i = k + 1

    def make_date(y, m, d):
        try:
            return _date(y, m, d).isoformat()
        except ValueError:
            return None

    def parse_date(s):
        s = s.strip()
        m = ISO_RE.match(s)
        if m:
            return make_date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        m = DMY_RE.match(s)
        if m:
            return make_date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
        m = DMONY_RE.match(s)
        if m:
            mon = MONTHS.get(m.group(2).lower())
            return make_date(int(m.group(3)), mon, int(m.group(1))) if mon else None
        m = MONDY_RE.match(s)
        if m:
            mon = MONTHS.get(m.group(1).lower())
            return make_date(int(m.group(3)), mon, int(m.group(2))) if mon else None
