        rows.append({"date": iso, "description": description,
                     "amount_inr": amount_inr})

    seen = set()
    unique = []
    for r in rows:
        key = (r["date"], r["description"], r["amount_inr"])
        if key in seen:
            continue
        seen.add(key)
        unique.append(r)

    return sorted(unique, key=lambda r: (r["date"], -abs(r["amount_inr"])))

