        return (int(g[0]), int(g[1]), int(g[2]))

    def _d_mon_y(g):
        mon = MONTHS.get(g[1].lower())
        return None if mon is None else (int(g[2]), mon, int(g[0]))

    def _mon_d_y(g):
        mon = MONTHS.get(g[0].lower())
        return None if mon is None else (int(g[2]), mon, int(g[1]))

