        # Amount may contain thousands commas, so the currency is after the last one.
        if ',' not in tail:
            return None
        amount_str, currency = tail.rsplit(',', 1)
        return date_str, desc.strip(), amount_str, currency.strip()

    rows = []
    seen = set()
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        fields = split_fields(line)
        if fields is None:
            continue
        date_str, description, amount_str, currency = fields
        if currency not in RATES:
            continue
        iso = parse_date(date_str)
        if iso is None:
            continue
        amount_inr = parse_amount(amount_str, currency)
        if amount_inr is None:
            continue
        key = (iso, description, amount_inr)
        if key in seen:
            continue
        seen.add(key)
        rows.append({"date": iso, "description": description,
                     "amount_inr": amount_inr})

    return sorted(rows, key=lambda r: (r["date"], -abs(r["amount_inr"])))

class LRUCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}     # key -> (value, stored_time)
        self._order = []    # least-recently-used first

    def _expired(self, key, now):
        return now - self._data[key][1] > self.ttl

    def _touch(self, key):
        if key in self._order:
            self._order.remove(key)
        self._order.append(key)

    def _drop(self, key):
        self._data.pop(key, None)
        if key in self._order:
            self._order.remove(key)

    def _purge(self, now):
        for k in list(self._order):
            if k in self._data and self._expired(k, now):
                self._drop(k)

    def put(self, key, value, now):
        if key in self._data:
            self._data[key] = (value, now)
            self._touch(key)
            return
        if len(self._data) >= self.capacity:
            self._purge(now)
        while len(self._data) >= self.capacity and self._order:
            self._drop(self._order[0])
        self._data[key] = (value, now)
        self._touch(key)

    def get(self, key, now):
        if key not in self._data:
            return None
        if self._expired(key, now):
            self._drop(key)
            return None
        self._touch(key)
        return self._data[key][0]

    def size(self, now):
        return sum(1 for k in self._data if not self._expired(k, now))

