def max_load(events):
    if not events:
        return (0, 0)

    deltas = []
    for start, end, weight in events:
        deltas.append((start, weight))
        deltas.append((end, -weight))
    deltas.sort()

    peak = 0
    peak_time = 0
    load = 0
    i = 0
    n = len(deltas)
    while i < n:
        t = deltas[i][0]
        # apply every delta at this timestamp before reading the load,
        # since [start, end) means ends and starts at t both settle first
        while i < n and deltas[i][0] == t:
            load += deltas[i][1]
            i += 1
        if load > peak:
            peak = load
            peak_time = t

    return (peak, peak_time)

def max_load(events):
    """Return (peak, t): the maximum instantaneous load and the earliest time it holds.

    Events are half-open [start, end), so at coordinate x the ends land before the
    starts. Collapsing both into one delta per coordinate handles that automatically.
    """
    if not events:
        return (0, 0)

    delta = {}
    for start, end, weight in events:
        delta[start] = delta.get(start, 0) + weight
        delta[end] = delta.get(end, 0) - weight

    peak = 0
    peak_t = 0
    load = 0
    for t in sorted(delta):
        load += delta[t]
        if load > peak:
            peak = load
            peak_t = t
    return (peak, peak_t)

def truncate_graphemes(s, n):
    """Truncate `s` to at most `n` user-perceived characters, appending "..." if cut."""
    import unicodedata

    ZWJ = "\u200d"
    clusters = []
    join_next = False  # a ZWJ is pending: the next code point must not start a cluster

    for ch in s:
        if ch == ZWJ:
            # Attaches to the current cluster and pulls the following code point in too.
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            join_next = True
        elif unicodedata.category(ch) == "Mn":
            # A combining mark always sticks to whatever it follows.
            if clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            join_next = False
        else:
            if join_next and clusters:
                clusters[-1] += ch
            else:
                clusters.append(ch)
            join_next = False

    if len(clusters) <= n:
        return s
    return "".join(clusters[:n]) + "..."

